/**
 * Assignment 5 website adapter. All HTTP calls are made through the
 * OpenAPI-generated TypeScript Fetch SDK, not through hand-written fetch().
 *
 * The client/ directory is generated by `npm run generate`.
 */
import {
  BooksApi,
  Configuration,
  OrdersApi,
  WarehouseApi,
  type BookInput,
} from "../client";
import type { Book, BookID, Filter, OrderId, ShelfId } from "./assignment-4";

const config = new Configuration({
  basePath: "http://localhost:3000",
});
const booksApi = new BooksApi(config);
const warehouseApi = new WarehouseApi(config);
const ordersApi = new OrdersApi(config);

function bookInput(book: Book): BookInput {
  return {
    name: book.name,
    author: book.author,
    description: book.description,
    price: book.price,
    image: book.image,
  };
}

async function listBooks(filters?: Filter[]): Promise<Book[]> {
  if (!filters?.length) return booksApi.listBooks();
  // The generated POST /books/search supports the Assignment 3 semantics:
  // AND within a filter group, OR between different groups.
  return booksApi.searchBooks({ searchBooksRequest: { filters } });
}

async function createOrUpdateBook(book: Book): Promise<BookID> {
  const updated = book.id
    ? await booksApi.updateBook({ id: book.id, bookInput: bookInput(book) })
    : await booksApi.createBook({ bookInput: bookInput(book) });
  return updated.id;
}

async function removeBook(book: BookID): Promise<void> {
  await booksApi.deleteBook({ id: book });
}

async function lookupBookById(book: BookID): Promise<Book> {
  return booksApi.getBook({ id: book });
}

async function placeBooksOnShelf(
  bookId: BookID,
  numberOfBooks: number,
  shelf: ShelfId,
): Promise<void> {
  await warehouseApi.placeBooksOnShelf({
    shelfPlacement: { bookId, numberOfBooks, shelf },
  });
}

async function orderBooks(order: BookID[]): Promise<{ orderId: OrderId }> {
  return ordersApi.placeOrder({ placeOrderRequest: { books: order } });
}

async function findBookOnShelf(
  book: BookID,
): Promise<Array<{ shelf: ShelfId; count: number }>> {
  return warehouseApi.getBookLocations({ bookId: book });
}

async function fulfilOrder(
  order: OrderId,
  booksFulfilled: Array<{
    book: BookID;
    shelf: ShelfId;
    numberOfBooks: number;
  }>,
): Promise<void> {
  await ordersApi.fulfilOrder({
    orderId: order,
    fulfillmentRequest: { fulfillment: booksFulfilled },
  });
}

async function listOrders(): Promise<
  Array<{
    orderId: OrderId;
    books: Record<BookID, number>;
  }>
> {
  return ordersApi.listOrders();
}

export default {
  assignment: "assignment-5",
  createOrUpdateBook,
  removeBook,
  listBooks,
  placeBooksOnShelf,
  orderBooks,
  findBookOnShelf,
  fulfilOrder,
  listOrders,
  lookupBookById,
};
